package com.luci.pianoroom;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
public final class SfzAutomationTest {
 static void check(boolean b,String s){SfzCompatibilityTest.check(b,s);}
 static final String NOTE="<region> sample=note.wav key=60 loop_mode=loop_continuous loop_start=0 loop_end=8191\n";
 public static void main(String[] args)throws Exception {
  File root=new File(args[0]);check(root.mkdirs(),"fresh automation folder");SfzCompatibilityTest.wav(root,"note.wav",24,2,false);
  String def="<control> set_cc7=100 set_cc20=40\n<global> amp_veltrack=0 amplitude_oncc7=100 amplitude_curvecc7=4 pan_oncc10=100 pan_curvecc10=1 ampeg_release=0.5 ampeg_dynamic=1 sustain_cc=90 ampeg_releasecc64=100 ampeg_release_curvecc64=11 ampeg_release_oncc72=2\n<curve> curve_index=11 v000=0 v032=0 v042=.1 v062=.4 v064=1 v127=1\n<master> volume_oncc20=-12 volume_curvecc20=2\n"+NOTE;
  ByteBuffer data=SfzCompatibilityTest.compile(root,def,"curves.prb");check(data.getInt(0)==0x37425250,"PRB7");check(Math.abs(data.getFloat(204+(4*128+100)*4)-100f*100/(127*127))<1e-7,"exact squared built-in volume curve");check(Math.abs(data.getFloat(204+(11*128+37)*4)-.05)<1e-7,"custom interpolated half pedal");check(InstrumentIndex.read(new File(root,"curves.prb"),"Curves",0).size()==1,"variable metadata catalog");long h=Synth.load(new File(root,"curves.prb").getPath());check(h!=0,"actual JNI PRB7");Synth.freeBank(h);
  for(String invalid:new String[]{"256","-1","11.5","NaN"})SfzCompatibilityTest.fails(root,def.replace("curvecc7=4","curvecc7="+invalid),"SFZ");
  SfzCompatibilityTest.fails(root,def.replace("curvecc7=4","curvecc7=12"),"não definida");SfzCompatibilityTest.fails(root,def.replace("v032=0","v128=0"),"v000");SfzCompatibilityTest.fails(root,def.replace("v032=0","v032=NaN"),"v032");SfzCompatibilityTest.fails(root,def.replace("curve_index=11","curve_index=4"),"curve_index");SfzCompatibilityTest.fails(root,def.replace("<master>","<curve> curve_index=11\n<master>"),"duplicada");
  SfzCompatibilityTest.compile(root,"<global> amplitude_oncc7=-100 amp_veltrack=0\n"+NOTE,"negative-volume.prb");
  String logic="<control> set_cc22=64\n<global> amp_veltrack=0\n<group> group=1 polyphony=1 key=-1 on_locc64=127 on_hicc64=127 locc22=1 off_by=2 off_mode=time off_time=.1\n<region> sample=note.wav lorand=0 hirand=.5\n<region> sample=note.wav lorand=.5 hirand=1\n<group> group=2 key=-1 on_locc64=0 on_hicc64=0 locc22=1 off_by=1\n<region> sample=note.wav\n";
  SfzCompatibilityTest.compile(root,logic,"pedal.prb");SfzCompatibilityTest.compile(root,"<global> amp_veltrack=0 amplitude_oncc21=-100 amplitude_curvecc21=1\n"+NOTE,"signed.prb");SfzCompatibilityTest.compile(root,"<global> amp_veltrack=0 amplitude_oncc21=0\n"+NOTE,"zero.prb");
  byte[] valid=Files.readAllBytes(new File(root,"curves.prb").toPath());File bad=new File(root,"bad.prb");for(int pos:new int[]{204,131276+160+20,131276+196+12}){byte[] corrupt=valid.clone();ByteBuffer.wrap(corrupt).order(ByteOrder.LITTLE_ENDIAN).putInt(pos,0x7fffffff);Files.write(bad.toPath(),corrupt);check(Synth.load(bad.getPath())==0,"corrupt table/count/amount safely rejected");}Files.write(bad.toPath(),Arrays.copyOf(valid,valid.length-1));check(Synth.load(bad.getPath())==0,"truncation safely rejected");
  if(args.length>1){File definition=new File(root,"Piano-Referencia.sfz");Files.copy(new File(args[1]).toPath(),definition.toPath());SfzSyntax.Document d=SfzSyntax.document(definition,root);check(d.regions.size()==1704&&d.curves.size()==2,"entire original definition parsed");Set<String> paths=new HashSet<>();for(Map<String,String> r:d.regions)paths.add(r.get("sample"));for(String sample:paths){File dest=SfzBank.safe(root,sample);dest.getParentFile().mkdirs();Files.copy(new File(root,"note.wav").toPath(),dest.toPath());}check(paths.size()==641,"all original 641 referenced sample paths");SfzBank.compile(definition,root,new File(root,"reference.prb"),"Piano-Referencia");h=Synth.load(new File(root,"reference.prb").getPath());check(h!=0,"original unchanged 1704-zone SFZ compiled with synthetic placeholder WAVs -> actual JNI");Synth.freeBank(h);System.out.println("PASS: received Piano-Referencia unchanged, all 1704 regions, 641 sample paths, original curves/groups/controllers, compiler -> JNI. WAVs are synthetic substitutes; original audio not provided.");}
  System.out.println("PASS: SFZ curves 0–6/custom interpolation, aliases, sparse live mappings, controller triggers, CC ranges, stereo, strict bounds, signed/zero amplitude, native corruption rejection.");
 }
}
